func alignCols(input: String, align: Align = .left) -> String {
  let widths = getColWidths(from: input)
  let lines = getLines(input: input)
  var res = ""

  for line in lines {
    for (str, width) in zip(line.components(separatedBy: "$"), widths) {
      let blanks = width - str.count
      let pre: Int, post: Int

      switch align {
      case .left:
        (pre, post) = (0, blanks)
      case .center:
        (pre, post) = (blanks / 2, (blanks + 1) / 2)
      case .right:
        (pre, post) = (blanks, 0)
      }

      res += String(repeating: " ", count: pre)
      res += str
      res += String(repeating: " ", count: post)
      res += " "
    }

    res += "\n"
  }

  return res
}

func solving(board: [[Int]]) -> [[Int]] {
	var board = board
	var isSolved = false
	while !isSolved {
		for x in 0 ..< 9  {
			for y in 0 ..< 9 {
				if board[x][y] == 0 {
					let known = Set(board.map { $0[y] } + board[x] + subgrid(board, pos: (x, y)))
					let possible = Set(Array(1...9)).subtracting(known)
					if possible.count == 1  {
						board[x][y] = possible.first!
					}
				}
			}
			isSolved = 45 == board[x].reduce(0, +)
		}
	}
	return board
}

