    // Initialize sum with first two terms: 1/0! + 1/1! = 1 + 1
    var sum = 2.0
    // factorial tracks n! for current iteration (starts at 1! = 1)
    var factorial: UInt64 = 1
    // n starts at 2 (next term to compute)
    var n: UInt64 = 2

    while true {
        // Compute next factorial = n! = (n-1)! * n
        let (newFactorial, factorialOverflow) = factorial.multipliedReportingOverflow(by: n)
        guard !factorialOverflow else {
            fatalError("Factorial computation overflow")
        }
        factorial = newFactorial

        // Calculate current term: 1/n!
        let term = 1.0 / Double(factorial)
        // Add term to cumulative sum
