    // Special case: any number mod 1 is 0
    if mod == 1 {
        return 0
    }

    // Validate mod != 0
    precondition(mod != 0, "mod must not be zero")

    // Handle edge case where division would overflow
    if base == Int.min && mod == -1 {
        fatalError("Division would cause overflow")
    }

    var base = base % mod  // Reduce base modulo mod (signed remainder)
    var exponent = exponent
    var result: Int = 1   // Initialize result

    // Process exponent using binary exponentiation
    while exponent > 0 {
        // If LSB of exponent is set
        if exponent & 1 != 0 {
            // Multiply result by current base (with overflow check)
            let (product, overflow) = result.multipliedReportingOverflow(by: base)
            guard !overflow else {
                fatalError("Multiplication overflow")
            }

            // Handle division edge case
            if product == Int.min && mod == -1 {
                fatalError("Division would cause overflow")
            }

            // Update result with modulo
            result = product % mod
        }

        // Square base for next bit (with overflow check)
        let (squared, overflow) = base.multipliedReportingOverflow(by: base)
        guard !overflow else {
            fatalError("Squaring overflow")
        }

        // Handle division edge case for squared value
