import Foundation

func lastSundays(of year: Int) -> [Date] {
    let calendar = Calendar.current
    var sundays = [Date]()

    for month in 1...12 {
        // Create components for last day of month
        var components = DateComponents()
        components.year = year
        components.month = month + 1  // Next month
        components.day = 0            // Day 0 = last day of previous month

        guard let lastDayOfMonth = calendar.date(from: components) else { 
            continue 
        }

        // Get weekday of last day (1 = Sunday, 7 = Saturday)
        let weekday = calendar.component(.weekday, from: lastDayOfMonth)

        // Calculate last Sunday
        if weekday == 1 {
            // Already Sunday
            sundays.append(lastDayOfMonth)
        } else {
            // Adjust backwards to previous Sunday
            let adjustedDay = calendar.component(.day, from: lastDayOfMonth) - (weekday - 1)
            components.month = month
            components.day = adjustedDay
            if let lastSunday = calendar.date(from: components) {
                sundays.append(lastSunday)
            }
        }
    }
    return sundays
}
```

