    // Initialize an empty result string
    var result = ""

    // Get sorted keys in descending order
    let sortedKeys = factors.keys.sorted().reversed()

    // Create iterator for the reversed collection
    var iterator = sortedKeys.makeIterator()

    // Process each factor
    while let base = iterator.next() {
        guard let exponent = factors[base] else { continue }

        // Build factor string based on exponent value
        let factorString: String
        if exponent == 1 {
            factorString = "\(base)"
        } else {
