struct Point: Equatable {
    let x: Double
    let y: Double
}

enum Orientation {
    case collinear
    case clockwise
    case counterClockwise
}

func calculateOrientation(p: Point, q: Point, r: Point) -> Orientation {
    let value = (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y)
    if value == 0 { return .collinear }
    return value > 0 ? .clockwise : .counterClockwise
}

func calculateConvexHull(fromPoints points: [Point]) -> [Point] {
    // Handle base cases
    guard points.count >= 3 else { return points }

    // Find starting point (lowest y, then leftmost)
    var startIndex = 0
    for i in points.indices {
        let p = points[i]
        let start = points[startIndex]
        if p.y < start.y || (p.y == start.y && p.x < start.x) {
            startIndex = i
        }
    }

    var hull = [Point]()
    var currentIndex = startIndex
    var nextIndex = 0

    repeat {
        hull.append(points[currentIndex])
        nextIndex = (currentIndex + 1) % points.count

        // Find next point in hull
        for i in points.indices {
            guard i != currentIndex else { continue }
            let orientation = calculateOrientation(
                p: points[currentIndex],
                q: points[i],
                r: points[nextIndex]
            )
            if orientation == .counterClockwise {
                nextIndex = i
            }
        }

        currentIndex = nextIndex
    } while currentIndex != startIndex

    return hull
}
```

