func centre(string: String, width: Int) -> String {
    let padding = width - string.count
    guard padding > 0 else { return string }
    let left = padding / 2
    let right = padding - left
    return String(repeating: " ", count: left) + string + String(repeating: " ", count: right)
}

func rpad(string: String, width: Int) -> String {
    string.count >= width ? string : string + String(repeating: " ", count: width - string.count)
}

func lpad(string: String, width: Int) -> String {
    string.count >= width ? string : String(repeating: " ", count: width - string.count) + string
}

func formatMonth(year: Int, month: Int) -> [String] {
