func place(_ remainingBlack: Int, 
           _ boardSize: Int, 
           blackQueens: inout [Position], 
           whiteQueens: inout [Position]) -> Bool {
    // Base case: all black queens placed
    if remainingBlack == 0 {
        return true
    }

    var isWhiteTurn = true
    var found = false

    outer: for i in 0..<boardSize {
        for j in 0..<boardSize {
            let newPos = (i, j)

            // Check if position is occupied
            if blackQueens.contains(where: { $0 == newPos }) 
            || whiteQueens.contains(where: { $0 == newPos }) {
                continue
            }

            if isWhiteTurn {
                // Check attacks against black queens
                for queen in blackQueens {
                    if isAttacking(newPos, queen) {
                        continue outer
                    }
                }

                // Place white queen
                whiteQueens.append(newPos)
                isWhiteTurn = false
            } else {
                // Check attacks against white queens
                for queen in whiteQueens {
                    if isAttacking(newPos, queen) {
                        continue outer
                    }
                }

                // Place black queen
                blackQueens.append(newPos)
                isWhiteTurn = true

                // Recurse with updated count
                if place(remainingBlack - 1, boardSize, 
                         blackQueens: &blackQueens, 
                         whiteQueens: &whiteQueens) {
                    return true
                }

                // Backtrack
                blackQueens.removeLast()
                whiteQueens.removeLast()
                found = true
            }
        }
    }

    // Backtrack white queen if placement failed
    if !isWhiteTurn {
        whiteQueens.removeLast()
    }

    return found
}

