import Foundation

// Custom sequence types
struct CycledSequence<Base: Sequence>: Sequence, IteratorProtocol {
    let base: Base
    var iterator: Base.Iterator
    var currentIterator: Base.Iterator

    init(_ base: Base) {
        self.base = base
        self.iterator = base.makeIterator()
        self.currentIterator = base.makeIterator()
    }

    mutating func next() -> Base.Element? {
        if let next = currentIterator.next() {
            return next
        } else {
            currentIterator = base.makeIterator()
            return currentIterator.next()
        }
    }
}

struct ChainedSequence<First: Sequence, Second: Sequence>: Sequence, IteratorProtocol 
where First.Element == Second.Element {
    var first: First.Iterator
    var second: Second.Iterator
    var isFirst: Bool = true

    init(_ first: First, with second: Second) {
        self.first = first.makeIterator()
        self.second = second.makeIterator()
    }

    mutating func next() -> First.Element? {
        if isFirst {
            if let next = first.next() {
                return next
            } else {
                isFirst = false
            }
        }
        return second.next()
    }
}

// Sequence extensions
extension Sequence {
    func cycled() -> CycledSequence<Self> {
        return CycledSequence(self)
    }

    func chained<Other: Sequence>(with other: Other) -> ChainedSequence<Self, Other> 
    where Self.Element == Other.Element {
        return ChainedSequence(self, with: other)
    }
}

// Continued fraction calculator
func continuedFraction<A: Sequence, B: Sequence>(_ aSeq: A, _ bSeq: B, iterations: Int) -> Double 
where A.Element == Int, B.Element == Int {
    var a = aSeq.makeIterator()
    var b = bSeq.makeIterator()
    var result = 0.0

    for _ in 0..<iterations {
        guard let aVal = a.next(), let bVal = b.next() else { break }
        result = Double(bVal) / (Double(aVal) + result)
    }
    return result
}

